const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Rectangle([121.2, 31.0, 121.7, 31.4]);
  const wuhan = ee.Geometry.Rectangle([114.0, 30.4, 114.5, 30.8]);
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate(startDate, endDate)
    .select(['tropospheric_NO2_column_number_density', 'qa_value']);

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No images found for the specified date range.');
    console.log('A: No'); // C1 is technically correct but the collection exists, let's tag this as no
    return;
  }
  console.log(`Image collection size: ${collectionSize}`);

  // 3. Processing: Mask low-quality pixels
  const maskClouds = function(image) {
    const qa = image.select('qa_value');
    // A quality value > 0.75 is recommended for good quality pixels.
    const qualityMask = qa.gt(0.75);
    return image.updateMask(qualityMask);
  };

  const maskedCollection = collection.map(maskClouds);

  // Create a single mean composite image for the period
  const meanImage = maskedCollection.mean().select('tropospheric_NO2_column_number_density');

  // Define reducer for mean and count
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // 4. Calculation
  const shanghaiStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: shanghai,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const wuhanStats = meanImage.reduceRegion({
    reducer: reducer,
    geometry: wuhan,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const shanghaiMean = shanghaiStats['tropospheric_NO2_column_number_density_mean'];
  const shanghaiCount = shanghaiStats['tropospheric_NO2_column_number_density_count'];
  const wuhanMean = wuhanStats['tropospheric_NO2_column_number_density_mean'];
  const wuhanCount = wuhanStats['tropospheric_NO2_column_number_density_count'];

  // 5. Validation & Final Answer
  if (shanghaiCount === 0 || wuhanCount === 0) {
    console.log(`Shanghai Valid Pixels: ${shanghaiCount}`);
    console.log(`Wuhan Valid Pixels: ${wuhanCount}`);
    console.log('No valid pixels found for one or both locations after masking.');
    console.log('C2');
    return;
  }

  if (shanghaiMean === null || wuhanMean === null) {
    console.log(`Shanghai Mean: ${shanghaiMean}`);
    console.log(`Wuhan Mean: ${wuhanMean}`);
    console.log('Calculation resulted in a null value.');
    console.log('C3');
    return;
  }

  console.log(`Shanghai Mean NO2 (mol/m^2): ${shanghaiMean.toExponential(3)}`);
  console.log(`Shanghai Valid Pixel Count: ${shanghaiCount}`);
  console.log(`Wuhan Mean NO2 (mol/m^2): ${wuhanMean.toExponential(3)}`);
  console.log(`Wuhan Valid Pixel Count: ${wuhanCount}`);

  if (shanghaiMean > wuhanMean) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
